lesson.code:
class Employee:
    def __init__(self, name, salary):
        self.name = name
        self.salary = salary

class Manager(Employee):
    def get_role(self):
        return "Team Leader"

m = Manager("Sarah", 95000)
print(f"{m.name}: ${m.salary} ({m.get_role()})")

class Animal:
    def speak(self):
        return "Some sound"

class Dog(Animal):
    def speak(self):       # Method overriding
        return "Woof!"

class Cat(Animal):
    def speak(self):
        return "Meow!"

for pet in [Dog(), Cat()]:
    print(pet.speak())   # Polymorphism in action

class Engine:
    def start(self):
        return "Vroom"

class Car:  # Composition: Car HAS AN Engine
    def __init__(self):
        self.engine = Engine()
    def drive(self):
        return self.engine.start()

print(Car().drive())

class Temperature:
    def __init__(self, celsius):
        self._celsius = celsius
    @property
    def fahrenheit(self):
        return self._celsius * 9/5 + 32
    @staticmethod
    def is_freezing(c):
        return c <= 0

t = Temperature(25)
print("Fahrenheit:", t.fahrenheit)
print("Freezing?", Temperature.is_freezing(-2))

# Proper super().__init__() call
class Person:
    def __init__(self, name):
        self.name = name
class Member(Person):
    def __init__(self, name, member_id):
        super().__init__(name)  # Parent init
        self.member_id = member_id

m = Member("Leo", 104)
print(f"{m.name}: #{m.member_id}")

class Circle:
    def __init__(self, radius):
        self.radius = radius
    @property
    def diameter(self):
        return self.radius * 2

c = Circle(10)
print("Diameter:", c.diameter)

