class Shape:
    def area(self):
        return 0
class Square(Shape):
    def __init__(self, side):
        self.side = side
    def area(self):
        return self.side ** 2
print(Square(6).area())

class Employee:
    def __init__(self, name, salary):
        self.name = name
        self.salary = salary
class Developer(Employee):
    def __init__(self, name, salary, prog_lang):
        super().__init__(name, salary)
        self.prog_lang = prog_lang
    def profile(self):
        return f"{self.name} earns ${self.salary} writing {self.prog_lang}"
dev = Developer('Maya', 90000, 'Python')
print(dev.profile())
